sys_script_include.script:
var UI_action_visibility = Class.create();
UI_action_visibility.prototype = {
    initialize: function() {},

    RefreshHoldingsData_Taskform: function(source, swiftattribute) {

        if ((source == gs.getProperty('x_hsb11_mss_c_proc.hsbcmss_el_custody_source_system_ghss') || source == gs.getProperty('x_hsb11_mss_c_proc.hsbcmss_el_custody_source_system_gcs')) && swiftattribute == 'Response Success-All fields updated(200)' && gs.getProperty('x_hsb11_mss_pos.hsbcmss_el_custodyPositiononDemand_active') == 'true') { // MSSCUSTODY 5521 - Added GCS as condition for the UK markets
            return 'true';
        } else {
            return 'false';
        }
    },

    type: 'UI_action_visibility'
};
